WITH flattened AS (SELECT id, service, log_ts, level, status_code, attr_key, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) e AS attr_key, value), enriched AS (SELECT *, PERCENT_RANK() OVER (ORDER BY status_code) AS status_code_percent_rank, ROUND(status_code / SUM(status_code) OVER (PARTITION BY level, service), 4) AS status_code_share, CUME_DIST() OVER (PARTITION BY level ORDER BY status_code) AS status_code_cume_dist FROM flattened), with_windows AS (SELECT *, RANK() OVER w_recent AS status_code_percent_rank_rank, SUM(status_code) OVER (PARTITION BY level, attr_key) AS level_sum_status_code, MIN(status_code_percent_rank) OVER (PARTITION BY attr_key) AS attr_key_min_status_code_percent_rank, RANK() OVER (PARTITION BY level, service ORDER BY status_code_cume_dist NULLS FIRST) AS status_code_cume_dist_rank, RANK() OVER (PARTITION BY service ORDER BY status_code DESC) AS status_code_rank FROM enriched WHERE status_code_percent_rank < 0.56 WINDOW w_recent AS (PARTITION BY attr_key, level ORDER BY status_code_percent_rank NULLS LAST)), kept_keys AS (SELECT service, id FROM with_windows INTERSECT SELECT service, id FROM app_logs WHERE level = 'ERROR'), reconciled AS (SELECT s.* FROM with_windows s JOIN kept_keys k ON s.service = k.service AND s.id = k.id) SELECT service, log_ts, level, attr_key, value, status_code_percent_rank, status_code_share, status_code_cume_dist, status_code_percent_rank_rank FROM reconciled;
